{
  "name": "opencode-tokscope",
  "version": "0.4.0",
  "description": "Model and provider throughput comparisons for OpenCode V2.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "tokens",
    "throughput"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mihaellenic/opencode-tokscope.git"
  },
  "author": "Mihael Lenic",
  "type": "module",
  "exports": {
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist/",
    "tui.js"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "bun scripts/build.ts",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "setup": "git config core.hooksPath githooks",
    "prepack": "bun run build"
  },
  "dependencies": {
    "@opencode/plugin": "2.1.2"
  },
  "peerDependencies": {
    "@opentui/core": "^0.8.0",
    "@opentui/solid": "^0.8.0",
    "solid-js": "^1.9.17"
  },
  "devDependencies": {
    "@opencode/client": "2.1.2",
    "@opentui/core": "0.8.0",
    "@opentui/keymap": "0.8.0",
    "@opentui/solid": "0.8.0",
    "solid-js": "1.9.17",
    "typescript": "5.7.3",
    "@types/bun": "1.4.0"
  }
}
